다음 CREATE TABLE문에서 '사번'을 기본키로, '이름'은 NULL을 허용하지 않도록 지정하려고 한다. 빈칸 (1), (2)에 들어갈 내용으로 옳은 것은?

CREATE TABLE 사원 (
  사번 NUMBER(4) ______(1)______,
  이름 VARCHAR2(20) ______(2)______,
  급여 NUMBER(10)
);

초기 사원 테이블이 비어 있는 상태에서 다음 트랜잭션을 순서대로 실행했다. 마지막 ROLLBACK TO SP1; 수행 후 사원 테이블에 남아있는 데이터로 옳은 것은?

INSERT INTO 사원 VALUES (100, '김민수');
INSERT INTO 사원 VALUES (101, '이영희');
SAVEPOINT SP1;
INSERT INTO 사원 VALUES (102, '박철수');
DELETE FROM 사원 WHERE 사번 = 100;
ROLLBACK TO SP1;
